attributes.cssVariables:
:root {
  /* ── palette ── Boxel Slate ink on Dove paper, Boxel Teal action.
     Compiled literals: no color math at render time. */
  --background: oklch(0.977 0.007 290);
  --canvas: oklch(0.96 0.008 290);
  --card: oklch(1 0 0);
  --card-foreground: var(--foreground);
  --popover: oklch(1 0 0);
  --popover-foreground: var(--foreground);
  --inset: oklch(0.968 0.008 290);
  --field: oklch(0.995 0.004 290);
  --hover: oklch(0.955 0.01 290);
  --stripe: oklch(0.984 0.007 290);
  --foreground: oklch(0.248 0.02 305);
  --muted: oklch(0.968 0.008 290);
  --muted-foreground: color-mix(in srgb, var(--foreground) 62%, var(--card));
  --ink-3: color-mix(in srgb, var(--foreground) 40%, var(--card));
  --border: oklch(0.929 0.011 290);
  --line-strong: oklch(0.875 0.013 290);
  --input: var(--border);
  --primary: oklch(0.888 0.193 164);
  --primary-foreground: oklch(0.248 0.02 305);
  --pretui-primary-ink: oklch(0.47 0.14 164);
  --secondary: oklch(0.517 0.257 277);
  --secondary-foreground: oklch(1 0 0);
  --accent: oklch(0.928 0.223 124);
  --accent-foreground: oklch(0.248 0.02 305);
  --pretui-selected: color-mix(in srgb, var(--primary) 12%, var(--card));
  --ring: color-mix(in srgb, var(--primary) 70%, var(--foreground));
  --destructive: oklch(0.663 0.196 24);
  --destructive-foreground: oklch(0.985 0.003 290);
  --success: color-mix(in srgb, oklch(0.82 0.19 150) 72%, var(--foreground));
  --warning: oklch(0.74 0.15 80);
  --pretui-warning-ink: oklch(0.48 0.11 80);
  --pretui-info: color-mix(in srgb, oklch(0.845 0.132 192) 70%, var(--foreground));
  /* attention means a human must act now — never decorative */
  --pretui-attention: oklch(0.558 0.288 308);
  /* chart hues are constructed: anchor 163 + n*72, matched value and chroma */
  --chart-1: oklch(0.72 0.16 163);
  --chart-2: oklch(0.72 0.16 235);
  --chart-3: oklch(0.72 0.16 307);
  --chart-4: oklch(0.72 0.16 19);
  --chart-5: oklch(0.72 0.16 91);
  --tooltip: oklch(0.248 0.02 305);
  --tooltip-foreground: oklch(0.975 0.007 290);

  /* ── depth is ONE property: every token starts with the hairline ── */
  --shadow-ink-soft: oklch(0.2 0.015 290 / 0.05);
  --shadow-ink-mid: oklch(0.2 0.015 290 / 0.08);
  --shadow-ink-strong: oklch(0.18 0.015 290 / 0.16);
  --pretui-shadow-hairline: 0 0 0 1px var(--border);
  --pretui-shadow-control: 0 0 0 1px var(--border), 0 1px 2px var(--shadow-ink-soft);
  --pretui-shadow-card: 0 0 0 1px var(--border), 0 1px 2px var(--shadow-ink-soft), 0 2px 6px var(--shadow-ink-soft);
  --pretui-shadow-raised: 0 0 0 1px var(--border), 0 2px 10px var(--shadow-ink-mid);
  --pretui-shadow-overlay: 0 0 0 1px var(--border), 0 8px 28px var(--shadow-ink-strong);
  --pretui-shadow-inset: inset 0 1px 2px var(--shadow-ink-strong);
  --pretui-edge-highlight: inset 0 1px 0 oklch(1 0 0 / 0.14);

  /* ── the 0.625rem radius law: one radius, structural identity ── */
  --radius: 10px;
  --radius-surface: 10px;
  --radius-chip: 6px;

  /* ── the IBM Plex trio ── */
  --font-sans: 'IBM Plex Sans', 'Helvetica Neue', Arial, system-ui, sans-serif;
  --font-serif: 'IBM Plex Serif', Georgia, serif;
  --font-mono: 'IBM Plex Mono', Menlo, ui-monospace, monospace;
  --track-heading: -0.02em;
  --track-ui: 0.01em;
  --track-eyebrow: 0.08em;
  --text-body: 15px;
  --leading-body: 24px;
  --text-ui-xs: 11px;
  --text-ui-sm: 11.5px;
  --text-ui: 12px;
  --text-ui-md: 12.5px;
  --text-heading: 19px;
  --text-display: 33px;
  --text-stat: 25px;

  /* ── spacing: one density knob, a 1.333 perfect-fourth ladder ── */
  --spacing: 4px;
  --space-1: var(--spacing);
  --space-2: calc(var(--spacing) * 1.5);
  --space-3: calc(var(--spacing) * 2);
  --space-4: calc(var(--spacing) * 2.75);
  --space-5: calc(var(--spacing) * 3.5);
  --space-6: calc(var(--spacing) * 4.75);
  --space-7: calc(var(--spacing) * 6.25);
  --space-8: calc(var(--spacing) * 8.5);
  --row-h: 32px;
  --control-h: 28px;

  /* ── house motion: pre-sampled springs, no runtime ── */
  --pretui-ease-enter: cubic-bezier(0.23, 1, 0.32, 1);
  --pretui-dur-enter: 250ms;
  --pretui-ease-snap: cubic-bezier(0.2, 0.9, 0.25, 1.05);
  --pretui-dur-snap: 180ms;
  --pretui-ease-morph: cubic-bezier(0.3, 0.7, 0.2, 1.02);
  --pretui-dur-morph: 300ms;

  color-scheme: light;
}

/* Re-declared per theme scope ON PURPOSE: a custom property's inner var()s
   resolve where they are DECLARED, so a light-only ladder would bake light
   borders and carry them into a dark subtree. */
.dark {
  --background: oklch(0.175 0.004 290);
  --canvas: oklch(0.205 0.004 290);
  --card: oklch(0.24 0.005 290);
  --popover: oklch(0.27 0.005 290);
  --inset: oklch(0.215 0.004 290);
  --field: oklch(0.265 0.005 290);
  --hover: oklch(0.285 0.005 290);
  --stripe: oklch(0.255 0.005 290);
  --foreground: oklch(0.965 0.007 290);
  --muted: oklch(0.285 0.005 290);
  --muted-foreground: oklch(1 0 0 / 0.62);
  --ink-3: oklch(1 0 0 / 0.38);
  --border: oklch(0.32 0.006 290);
  --line-strong: oklch(0.38 0.006 290);
  --input: oklch(0.34 0.006 290);
  --primary-foreground: oklch(0.2 0.04 262);
  --pretui-primary-ink: var(--primary);
  --pretui-warning-ink: var(--warning);
  --pretui-selected: color-mix(in srgb, var(--primary) 14%, var(--card));
  --ring: var(--primary);
  --success: oklch(0.82 0.19 150);
  --tooltip: oklch(0.14 0.004 290);
  --chart-1: oklch(0.76 0.16 163);
  --chart-2: oklch(0.76 0.16 235);
  --chart-3: oklch(0.76 0.16 307);
  --chart-4: oklch(0.76 0.16 19);
  --chart-5: oklch(0.76 0.16 91);
  /* dark is matte carbon: luminance does the work, shadows barely exist */
  --shadow-ink-soft: oklch(0.2 0.015 290 / 0.35);
  --shadow-ink-mid: oklch(0.2 0.015 290 / 0.45);
  --shadow-ink-strong: oklch(0.18 0.015 290 / 0.6);
  --pretui-shadow-hairline: 0 0 0 1px var(--border);
  --pretui-shadow-control: 0 0 0 1px var(--border), 0 1px 2px var(--shadow-ink-soft);
  --pretui-shadow-card: 0 0 0 1px var(--border), 0 1px 2px var(--shadow-ink-soft), 0 2px 6px var(--shadow-ink-soft);
  --pretui-shadow-raised: 0 0 0 1px var(--border), 0 2px 10px var(--shadow-ink-mid);
  --pretui-shadow-overlay: 0 0 0 1px var(--border), 0 8px 28px var(--shadow-ink-strong);
  --pretui-shadow-inset: inset 0 1px 2px var(--shadow-ink-strong);
  --pretui-edge-highlight: inset 0 1px 0 oklch(1 0 0 / 0.08);
  color-scheme: dark;
}
